mapper.select:
SELECT id, order_code, status, created_date
FROM sales
WHERE id = #{id}

mapper.update:
UPDATE sales
SET status = #{status},
    modified_date = NOW(),
    modified_by = #{modifiedBy}
WHERE id = #{id}
  AND created_date >= DATE_SUB(NOW(), INTERVAL 30 DAY)

mapper.select:

SELECT s.id, s.order_code, s.status, s.created_date
FROM sales s
WHERE 1=1


  AND s.order_code = #{orderCode}


  AND s.created_date >= #{startDate}


  AND s.created_date < #{endDate}


ORDER BY s.created_date DESC
